<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\ValueObject\Accessor\UserMfaRecoveryCodeUsedAtAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserMfaRecoveryCodeUsedAtAccessor trait.
 *
 * Covers null default, string/VO assignment via withUsedAt,
 * getUsedAt/usedAt accessors, and isUsedAtChanged with/without original.
 */
class UserMfaRecoveryCodeUsedAtAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withUsedAt creates a new instance with the UsedAt set
     * from a string value, and getUsedAt returns the primitive string.
     */
    public function testWithUsedAtFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserMfaRecoveryCodeUsedAtAccessorUnitTest();

        // Act
        $result = $holder->withUsedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->getUsedAt());
    }
    /**
     * Asserts that withusedAt has access to the value object
     * from a string value, and getUsedAt returns the primitive string.
     */
    public function testWithUsedAtFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserMfaRecoveryCodeUsedAtAccessorUnitTest();

        // Act
        $result = $holder->withUsedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->usedAt()->value());
    }
    public function testChangedUsedAt(): void
    {
        // Arrange
        $holder = new ImplWithUserMfaRecoveryCodeUsedAtAccessorUnitTest();
        $original = $holder->withUsedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $same = $holder->withUsedAt((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $modified = $holder->withUsedAt((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')));

        // Act
        $unchanged = $holder->isUsedAtChanged();
        $withSame = $original->isUsedAtChanged($same);
        $withDiferent = $original->isUsedAtChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserMfaRecoveryCodeUsedAtAccessorUnitTest
{
    use UserMfaRecoveryCodeUsedAtAccessor;
}
